# ---------- 가나 → 한글 ----------
CHO="ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ"; JUNG="ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ"; JONG=" ㄱㄲㄳㄴㄵㄶㄷㄹㄺㄻㄼㄽㄾㄿㅀㅁㅂㅄㅅㅆㅇㅈㅊㅋㅌㅍㅎ"
def syl(c,v,j=" "): return chr(0xAC00+(CHO.index(c)*21+JUNG.index(v))*28+JONG.index(j))
K={}
rows={"":"ㅇ","k":"ㅋ","g":"ㄱ","s":"ㅅ","z":"ㅈ","t":"ㅌ","d":"ㄷ","n":"ㄴ","h":"ㅎ","b":"ㅂ","p":"ㅍ","m":"ㅁ","y":"ㅇ","r":"ㄹ","w":"ㅇ"}
V={"a":"ㅏ","i":"ㅣ","u":"ㅜ","e":"ㅔ","o":"ㅗ"}
H="あいうえおかきくけこがぎぐげごさしすせそざじずぜぞたちつてとだぢづでどなにぬねのはひふへほばびぶべぼぱぴぷぺぽまみむめもやゆよらりるれろわを"
R=["a","i","u","e","o","ka","ki","ku","ke","ko","ga","gi","gu","ge","go","sa","shi","su","se","so","za","ji","zu","ze","zo","ta","chi","tsu","te","to","da","ji","zu","de","do","na","ni","nu","ne","no","ha","hi","fu","he","ho","ba","bi","bu","be","bo","pa","pi","pu","pe","po","ma","mi","mu","me","mo","ya","yu","yo","ra","ri","ru","re","ro","wa","o"]
def romaji_to_syl(r):
    sp={"shi":("ㅅ","ㅣ"),"chi":("ㅊ","ㅣ"),"tsu":("ㅊ","ㅡ"),"ji":("ㅈ","ㅣ"),"fu":("ㅎ","ㅜ"),"zu":("ㅈ","ㅡ"),"su":("ㅅ","ㅡ"),
        "ya":("ㅇ","ㅑ"),"yu":("ㅇ","ㅠ"),"yo":("ㅇ","ㅛ"),"wa":("ㅇ","ㅘ"),"ka":("ㅋ","ㅏ"),"ta":("ㅌ","ㅏ")}
    if r in sp: return sp[r]
    c=rows[r[:-1]] if len(r)>1 else "ㅇ"; return (c,V[r[-1]])
for h,r in zip(H,R):
    K[h]=romaji_to_syl(r)
    K[chr(ord(h)+0x60)]=romaji_to_syl(r)
# 요음
YO={"ゃ":"ㅑ","ゅ":"ㅠ","ょ":"ㅛ","ャ":"ㅑ","ュ":"ㅠ","ョ":"ㅛ"}
SMALLV={"ぁ":"ㅏ","ぃ":"ㅣ","ぅ":"ㅜ","ぇ":"ㅔ","ぉ":"ㅗ","ァ":"ㅏ","ィ":"ㅣ","ゥ":"ㅜ","ェ":"ㅔ","ォ":"ㅗ"}
def kana2hangul(s):
    out=[];i=0
    while i<len(s):
        ch=s[i]
        if ch in "んン":
            if out and isinstance(out[-1],list) and out[-1][2]==" ": out[-1][2]="ㄴ"
            else: out.append(["ㅇ","ㅡ","ㄴ"])
            i+=1;continue
        if ch in "っッ":
            if out and isinstance(out[-1],list) and out[-1][2]==" ": out[-1][2]="ㅅ"
            i+=1;continue
        if ch=="ー": i+=1;continue
        if ch=="ヴ": out.append(["ㅂ","ㅜ"," "]);i+=1;continue
        if ch in K:
            c,v=K[ch]
            if i+1<len(s) and s[i+1] in YO:
                v=YO[s[i+1]]
                if c in "ㅅㅈㅊ": v={"ㅑ":"ㅑ","ㅠ":"ㅠ","ㅛ":"ㅛ"}[v]; v={"ㅑ":"ㅏ","ㅠ":"ㅜ","ㅛ":"ㅗ"}[v]
                i+=1
            elif i+1<len(s) and s[i+1] in SMALLV:
                v=SMALLV[s[i+1]]
                if (c,v)==("ㅎ","ㅏ") or c=="ㅎ": c="ㅍ"
                i+=1
            out.append([c,v," "]);i+=1;continue
        if ch in SMALLV: out.append(["ㅇ",SMALLV[ch]," "]);i+=1;continue
        out.append(ch);i+=1
    return "".join(syl(*x) if isinstance(x,list) else x for x in out)

def tr(title):
    t=re.sub(r"【[^】]*】","",title).strip()
    t=re.sub(r"^ちいかわ\s+","",t)
    i=0;res=""
    while i<len(t):
        for k in KEYS:
            if t.startswith(k,i): res+=D[k];i+=len(k);break
        else: res+=t[i];i+=1
    res=re.sub(r"[ぁ-んァ-ンヴー]+",lambda m:kana2hangul(m.group()),res)
    res=res.replace("（"," (").replace("）",")").replace("／","/").replace("＆","&").replace("！","! ").replace("？","?").replace("　"," ")
    res=re.sub(r"\s+"," ",res).replace("( ","(").replace(" )",")").strip()
    return res
